const run = async (setVSeed) => {
  const { VQuery } = await import('@visactor/vquery')
  const vquery = new VQuery()

  const rawDataset = [
    { area: 'BEI JING', date: '2025-01-01', sales: 100 },
    { area: 'BEI JING', date: '2025-01-02', sales: 200 },
    { area: 'BEI JING', date: '2025-01-03', sales: 300 },

    { area: 'HANG ZHOU', date: '2025-01-01', sales: 100 },
    { area: 'HANG ZHOU', date: '2025-01-02', sales: 200 },
    { area: 'HANG ZHOU', date: '2025-01-03', sales: 500 },

    { area: 'SHANG HAI', date: '2025-11-01', sales: 600 },
    { area: 'SHANG HAI', date: '2025-11-02', sales: 400 },
    { area: 'SHANG HAI', date: '2025-11-03', sales: 300 },
  ]

  const datasetId = 'vquery-demo'

  if (await vquery.hasDataset(datasetId)) {
    await vquery.dropDataset(datasetId)
  }

  const schema = [
    { name: 'area', type: 'string' },
    { name: 'date', type: 'date' },
    { name: 'sales', type: 'number' },
  ]
  await vquery.createDataset(datasetId, schema, { type: 'json', rawDataset })

  const dataset = await vquery.connectDataset(datasetId)

  const queryDSL = {
    select: [
      'area',
      {
        field: 'sales',
        alias: 'Sum(sales)',
        aggr: {
          func: 'sum',
        },
      },
      {
        field: 'date',
        alias: 'year',
        aggr: {
          func: 'to_year',
        },
      },
    ],
    groupBy: ['year', 'area'],
    orderBy: [
      {
        field: 'Sum(sales)',
        order: 'desc',
      },
    ],
    where: {
      op: 'and',
      conditions: [
        {
          op: 'or',
          conditions: [
            {
              field: 'area',
              op: 'in',
              value: ['BEI JING'],
            },
            {
              field: 'sales',
              op: '>=',
              value: 400,
            },
          ],
        },
      ],
    },
    limit: 100,
  }

  const queryResult = await dataset.query(queryDSL)
  await dataset.disconnect()
  await vquery.close()

  const vseed = {
    dataset: queryResult.dataset,
    chartType: 'table',
    locale: 'zh-CN',
  }

  setVSeed(() => vseed)
}

const Demo = () => {
  const [vseed, setVSeed] = useState<VSeed>()

  useEffect(() => {
    run(setVSeed)
  }, [])

  return vseed && <SimpleVSeedRender vseed={vseed} />
}





import {
  registerAll,
  VSeed,
  Builder,
  isPivotChart,
  isVChart,
  isPivotTable,
  isTable,
  zVSeed,
  ColorIdEncoding,
} from '@visactor/vseed'

registerAll()
register.chartModule('vchart', VChart)

const SimpleVSeedRender = (props: { vseed: VSeed }) => {
  const { vseed } = props
  const ref = useRef<HTMLDivElement>(null)
  const builderRef = useRef<Builder>()
  const dark = useDark()
  useEffect(() => {
    if (!ref.current) {
      return
    }
    const theme = dark ? 'dark' : 'light'
    const builder = Builder.from({ ...vseed, theme })
    const spec = builder.build()

    builderRef.current = builder
    if (isPivotChart(vseed)) {
      const tableInstance = new PivotChart(ref.current, spec)

      tableInstance.on('legend_item_click', (args) => {
        console.log('LEGEND_ITEM_CLICK', args)
        tableInstance.updateFilterRules([
          {
            filterKey: ColorIdEncoding,
            filteredValues: args.value,
          },
        ])
      })

      tableInstance.on('legend_change', (args) => {
        const maxValue = args.value[1]
        const minValue = args.value[0]
        tableInstance.updateFilterRules([
          {
            filterFunc: (record) => {
              const value = record[record[ColorIdEncoding]]
              if (value >= minValue && value <= maxValue) {
                return true
              }
              return false
            },
          },
        ])
      })

      return () => tableInstance.release()
    } else if (isVChart(vseed)) {
      const vchart = new VChart(spec, { dom: ref.current })
      vchart.renderSync()
      return () => vchart.release()
    } else if (isTable(vseed)) {
      const tableInstance = new ListTable(ref.current, spec)
      return () => tableInstance.release()
    } else if (isPivotTable(vseed)) {
      const tableInstance = new PivotTable(ref.current, spec)
      return () => tableInstance.release()
    }
  }, [vseed, dark])

  return (
    <div
      ref={ref}
      style={{ height: 300, width: '100%' }}
      onClick={() => {
        console.group(`selected ${vseed.chartType}`)
        console.log('builder', builderRef.current)
        console.log('spec', builderRef.current.spec)
        console.log('vseed', builderRef.current.vseed)
        console.log('advancedVSeed', builderRef.current.advancedVSeed)
        console.groupEnd()
      }}
    >
      {' '}
    </div>
  )
}

export default Demo

:::info Einfach und zugleich raffiniert
Dies ist eines der interessantesten und zugleich zentralsten Module von VSeed. Es wirkt komplex, ist tatsächlich aber sehr einfach und raffiniert und umfasst weniger als 200 Zeilen Code.

Wenn foldMeasures und unfoldDimensions sinnvoll eingesetzt werden, lassen sich beliebige Measures und Dimensions in feste Measures und Dimensions umwandeln. Dadurch wird eine ausreichend flexible visuelle Zuordnung möglich.
:::

foldMeasures

Position des Quellcodes

foldMeasures foldet alle Measures zu einem Measure, ergänzt eine Measure-Name-Dimension und eine Measure-Id-Dimension. Alle potenziell verlorenen Informationen werden in foldInfo gespeichert; außerdem können während dieses Prozesses Datenstatistiken berechnet werden.

Eigenschaften

Eigenschaft 1: Nach der Ausführung von foldMeasures gibt es garantiert nur noch 1 Measure-Feld. Das bedeutet, dass Daten mit mehreren Measures in 1 Measure umgewandelt werden können und beliebige Mehr-Measure-Daten genau einem grafischen Element zugeordnet werden.

Eigenschaft 2: Dateneintrag und Daten des grafischen Elements (geometrischen Elements) stimmen strikt überein. Ein Dateneintrag entspricht einem grafischen Element.

Eigenschaft 3: Während dieses Prozesses werden Datenstatistiken berechnet.

:::tip Der raffinierteste Punkt!!!

1 Measure und 0 Dimensions ergeben nach foldMeasures 1 Measure und 2 Dimensions (einschließlich Measure-Name und Measure-Id).

4 Measures und 1 Dimension ergeben nach 2 Durchläufen von foldMeasures 2 Measures und 3 Dimensions (einschließlich Measure-Name und Measure-Id), wodurch Szenarien wie Dual-Axis-Charts sauber unterstützt werden.

N Measures und 0 Dimensions ergeben nach Y (Y ≤ N) Durchläufen von foldMeasures Y Measures und 2 Dimensions (einschließlich Measure-Name und Measure-Id).

:::

Minimal lauffähiges Beispiel

const data = [
  { category: 'A', sales: 100, profit: 30 },
  { category: 'B', sales: 200, profit: 50 },
]

const measures = [
  { id: 'sales', alias: 'Sales' },
  { id: 'profit', alias: 'Profit' },
]

function foldMeasures(dataset, measures, options) {
  const {
    measureId,
    measureName,
    measureValue,
    colorMeasureId,
    allowEmptyFold = true,
  } = options || {}

  const foldInfo = {
    measureId,
    measureName,
    measureValue,
    statistics: {
      max: -Infinity,
      min: Infinity,
      sum: 0,
      count: 0,
      colorMin: Infinity,
      colorMax: -Infinity,
    },
    foldMap: {},
  }

  const ids = measures.map(m => m.id)
  const result = []

  for (const row of dataset) {
    for (const measure of measures) {
      const { id, alias } = measure
      const newRow = { ...row }

      // Andere Measure-Felder entfernen, um Duplikate zu vermeiden
      for (const key of ids) {
        delete newRow[key]
      }

      newRow[measureId] = id
      newRow[measureName] = alias || id
      newRow[measureValue] = row[id]

      if (colorMeasureId) {
        const colorValue = row[colorMeasureId]
        newRow.color = colorValue
        foldInfo.statistics.colorMin = Math.min(foldInfo.statistics.colorMin, Number(colorValue))
        foldInfo.statistics.colorMax = Math.max(foldInfo.statistics.colorMax, Number(colorValue))
      }

      const val = Number(row[id])
      foldInfo.statistics.min = Math.min(foldInfo.statistics.min, val)
      foldInfo.statistics.max = Math.max(foldInfo.statistics.max, val)
      foldInfo.statistics.sum += val
      foldInfo.statistics.count++

      foldInfo.foldMap[id] = alias

      result.push(newRow)
    }
  }

  return { dataset: result, foldInfo }
}

